void demNguoc(int n){
    if(n > 0){
        printf("%d ", n);
        demNguoc(n - 1);
    }
}
// demNguoc(4) in: 4 3 2 1

int sum(int n){
    if(n == 0) return 0;
    return n + sum(n - 1);
}

void dequy(int n){
    if(n > 0){
        printf("goi n=%d\n", n);
        dequy(n - 1);
    }
    printf("n=%d ket thuc\n", n);
}

int F(int n){ return (n==0||n==1) ? n : F(n-1)+F(n-2); }

long long giaithua(int n){ return n==0 ? 1 : n*giaithua(n-1); }

int tongchuso(int n){ return n<10 ? n : n%10 + tongchuso(n/10); }

void loop(){
    printf("codelab\n");
    loop();   // không có điều kiện dừng
}
